/**
 * ═══════════════════════════════════════════════════════════════
 *  NODE:  Prepare Data
 *  MODE:  Run Once for All Items
 *  IN:    Extract Receipt Data  (Gemini → raw JSON string)
 *  OUT:   Clean typed fields + image binary, ready for Drive & Sheets
 * ═══════════════════════════════════════════════════════════════
 *  Responsibilities:
 *    1. Parse Gemini's JSON string into real fields
 *    2. NORMALISE + VALIDATE every field (never trust an LLM's types)
 *    3. Convert Telegram's UTC timestamp to a local calendar date
 *    4. Generate a filesystem-safe, descriptive filename
 *    5. Recompute `status` from the CLEANED values, not Gemini's claim
 *    6. Carry the image binary forward (Gemini strips it)
 * ═══════════════════════════════════════════════════════════════
 */

// ══ CONFIG ═════════════════════════════════════════════════════

// Timezone for BOTH the Drive folder name and the "Logged At" column.
// Telegram sends UTC. Manila is UTC+8, so a receipt submitted at 07:00
// local is 23:00 the PREVIOUS DAY in UTC. Without this, every receipt
// sent before 08:00 lands in yesterday's folder.
const TZ = 'Asia/Manila';

// Closed vocabularies. A closed enum keeps the Sheet columns groupable —
// open-ended AI output yields "Food", "food", "Dining", "Restaurant" for
// the same concept and fragments every pivot table.
const CATEGORIES = ['Food', 'Groceries', 'Transport', 'Utilities',
                    'Office Supplies', 'Health', 'Entertainment', 'Other'];
const PAYMENTS   = ['Cash', 'Card', 'GCash', 'Bank Transfer', 'Other'];

// ══ NORMALISERS ════════════════════════════════════════════════
// Gemini follows the prompt ~99% of the time. These functions handle
// the other 1% so a stray response can never poison the spreadsheet.

/** Trim to a clean string, or null. Empty/whitespace-only → null. */
const text = (v) => {
  const s = String(v ?? '').trim();
  return s === '' || s.toLowerCase() === 'null' ? null : s;
};

/**
 * FIX #1 — Force numeric.
 * The prompt says "digits only", but if Gemini ever returns "₱1,250.00"
 * or the string "102.98", the Sheet's Number-formatted column receives
 * text and every SUM() silently breaks. We strip non-numeric characters
 * and coerce. Non-numeric garbage becomes null, never NaN — NaN written
 * to Sheets appears as a literal "NaN" cell.
 */
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};

/**
 * FIX #2 — Enforce ISO date shape.
 * If Gemini returns "10/07/2020" we CANNOT know if that's 10 July or
 * 7 October. An ambiguous date is worse than no date, because it looks
 * valid. Anything not matching YYYY-MM-DD is rejected outright.
 */
const isoDate = (v) => {
  const s = text(v);
  return s && /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : null;
};

/** Currency must be a 3-letter ISO 4217 code, else null. */
const currency = (v) => {
  const s = (text(v) ?? '').toUpperCase();
  return /^[A-Z]{3}$/.test(s) ? s : null;
};

/**
 * FIX #3 — Snap to the closed vocabulary.
 * Case-insensitive match against the allowed list; anything invented
 * (e.g. "Fuel", "Gas Station") collapses to "Other" rather than
 * creating a new category nobody expected.
 */
const oneOf = (v, list, fallback) => {
  const s = text(v);
  if (!s) return fallback;
  return list.find((x) => x.toLowerCase() === s.toLowerCase()) ?? fallback;
};

/**
 * Make an AI-generated string safe inside a filename.
 *
 * SECURITY: merchant names come from an LLM reading an untrusted image.
 * Characters like / \ .. : are illegal or dangerous in paths
 * (path traversal). We allow ONLY [a-zA-Z0-9] and collapse the rest.
 *
 *   "FUEL DEPOT #12/A"  →  "FUEL-DEPOT-12-A"
 */
const slug = (s) => (s || 'Unknown')
  .replace(/[^a-zA-Z0-9]+/g, '-')   // any run of non-alphanumerics → one "-"
  .replace(/^-+|-+$/g, '')          // trim leading/trailing hyphens
  .slice(0, 40) || 'Unknown';       // cap length; catch input like "***"

// ══ DATE FORMATTERS ════════════════════════════════════════════

/**
 * "YYYY-MM-DD" in the configured timezone.
 * 'en-CA' is a deliberate trick — it natively produces ISO order.
 * '2-digit' guarantees zero-padding (08, not 8) so folders sort right.
 */
const fmtDate = (d) => new Intl.DateTimeFormat('en-CA', {
  timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit',
}).format(d);

/**
 * "HH:mm:ss" 24-hour in the configured timezone.
 * hour12:false avoids AM/PM, which breaks lexical sorting.
 */
const fmtTime = (d) => new Intl.DateTimeFormat('en-GB', {
  timeZone: TZ, hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false,
}).format(d);

// ══ MAIN ═══════════════════════════════════════════════════════

// Cache the array — $input.all() is a function call, not a property.
const items   = $input.all();
const results = [];

// Loop by index to align this item with the SAME item from earlier
// nodes. Index alignment is valid because every node in this branch
// is strictly 1-in / 1-out.
for (let i = 0; i < items.length; i++) {

  // ── 1. Pull Gemini's raw response ──────────────────────────
  // Path confirmed from live output: content.parts[0].text
  // Optional chaining prevents a hard crash if the node's output
  // shape changes after an update — we degrade to '' instead.
  // We read ONLY .text and deliberately ignore .thoughtSignature,
  // a multi-KB reasoning blob that would bloat every execution log.
  const raw    = items[i].json?.content?.parts?.[0]?.text ?? '';

  // 'STOP' = finished normally. 'MAX_TOKENS' = cut off mid-JSON.
  const finish = items[i].json?.finishReason ?? 'UNKNOWN';

  // ── 2. Strip fences, then parse ────────────────────────────
  // The prompt forbids markdown fences and Gemini complies, but LLMs
  // are probabilistic — occasionally one wraps JSON in ```json ... ```.
  // Stripping is cheap; a JSON.parse crash costs a lost receipt.
  const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

  let parsed     = {};
  let parseOk    = true;
  try {
    parsed = JSON.parse(cleaned);
  } catch (err) {
    // GRACEFUL DEGRADATION: unparseable output produces a flagged row,
    // not a dead execution. The receipt shows up as NEEDS_REVIEW
    // instead of vanishing silently.
    parseOk = false;
  }

  // ── 3. Normalise every field ───────────────────────────────
  // Nothing from the model reaches the Sheet unvalidated.
  const merchant      = text(parsed.merchant);
  const receiptDate   = isoDate(parsed.receipt_date);
  const totalAmount   = num(parsed.total_amount);
  const tax           = num(parsed.tax);
  const currencyCode  = currency(parsed.currency);
  const category      = oneOf(parsed.category,       CATEGORIES, 'Other');
  const paymentMethod = oneOf(parsed.payment_method, PAYMENTS,   null);

  // ── 4. FIX #4 — Recompute status from CLEANED values ───────
  // We do NOT trust Gemini's own "status" field. It might report "OK"
  // while returning a malformed date that our validator just nulled.
  // Deriving status here guarantees it always reflects what actually
  // landed in the Sheet — a single source of truth for the Telegram
  // reply and for any human reviewing the log.
  let status = (merchant && receiptDate && totalAmount !== null)
    ? 'OK'
    : 'NEEDS_REVIEW';

  // Truncated or unparseable responses are untrustworthy regardless
  // of whether the individual fields happen to look fine.
  if (!parseOk || finish !== 'STOP') status = 'NEEDS_REVIEW';

  // ── 5. Derive dates from the Telegram message ──────────────
  // Referenced by NODE NAME — renaming 'Telegram Trigger' breaks this.
  const msg = $('Telegram Trigger').all()[i].json.message;

  // msg.date is Unix SECONDS; JavaScript Date wants MILLISECONDS.
  // Omitting * 1000 yields January 1970.
  const submittedAt = new Date(msg.date * 1000);

  // THIS is the "group by submission date" requirement. Deliberately
  // the submission date, NOT the receipt's printed date — which can be
  // years old (ours reads 2020-07-10).
  const folderName = fmtDate(submittedAt);

  // Audit trail: when OUR system processed it, to the second.
  const loggedAt   = `${folderName} ${fmtTime(submittedAt)}`;

  // ── 6. FIX #5 — Build the filename defensively ─────────────
  // Telegram's photo path re-encodes images and discards metadata, so
  // every upload arrives named "file_0.jpg". Uploading that verbatim
  // gives a Drive folder of identical filenames.

  // Array.isArray guard: when we later wire the `document` branch into
  // this node, msg.photo will be undefined. Without this the node
  // throws instead of degrading. Forward-compatible by design.
  const photos       = Array.isArray(msg.photo) ? msg.photo : [];

  // Last element = highest resolution (Telegram orders small → large).
  const largest      = photos.length ? photos[photos.length - 1] : null;

  // Works for both branches; null if neither is present.
  const fileUniqueId = largest?.file_unique_id
                    ?? msg.document?.file_unique_id
                    ?? null;

  // Preserve a real extension when one exists (document branch),
  // otherwise default to jpg (photo branch is always JPEG).
  const ext = (msg.document?.file_name?.split('.').pop() ?? 'jpg')
                .toLowerCase().replace(/[^a-z0-9]/g, '') || 'jpg';

  // THE DOT FIX: "102.98" would make Drive report fullFileExtension as
  // "98_msg5.jpg", because Drive treats everything after the FIRST dot
  // as the extension. Swapping "." for "-" keeps exactly one dot in the
  // filename — the real one before the extension.
  //   102.98  →  102-98
  const amountTag = totalAmount === null
    ? 'NA'
    : String(totalAmount).replace('.', '-');

  // message_id is unique per chat, guaranteeing no overwrite even if
  // two identical receipts arrive the same day.
  //   → 2026-08-31_FUEL-DEPOT_102-98_msg5.jpg
  const fileName = `${folderName}_${slug(merchant)}_${amountTag}_msg${msg.message_id}.${ext}`;

  // ── 7. Emit the item ───────────────────────────────────────
  results.push({
    json: {
      // — Bookkeeping / audit —
      loggedAt,       // when we processed it (local time)
      folderName,     // Drive folder target  (YYYY-MM-DD)
      fileName,       // generated Drive filename

      // — Validated receipt data —
      merchant,       // trimmed string or null
      receiptDate,    // strict YYYY-MM-DD or null — date PRINTED on receipt
      totalAmount,    // NUMBER or null — must stay summable in Sheets
      currency:       currencyCode,   // separate column so amount stays numeric
      tax,            // NUMBER or null
      category,       // guaranteed one of CATEGORIES
      paymentMethod,  // one of PAYMENTS, or null
      status,         // OK | NEEDS_REVIEW → drives the Telegram reply

      // — Telegram context —
      // .trim() handles users with no last name.
      submittedBy:  `${msg.from?.first_name ?? ''} ${msg.from?.last_name ?? ''}`.trim() || 'Unknown',

      chatId:       msg.chat.id,      // needed to reply at the end of the flow
      messageId:    msg.message_id,   // dedup key: catches retries of one message
      fileUniqueId,                   // dedup key: catches the SAME IMAGE resent
    },

    // ⚠️ CRITICAL — do not delete this line.
    // The Gemini node returns text only; the image binary is NOT on
    // items[i], and Code nodes don't auto-forward binary. We pull it
    // back from 'Download Photo', or 'Upload to Drive' fails with
    // "no binary data" — the #1 gotcha in this workflow.
    binary: $('Download Photo').all()[i].binary,
  });
}

// n8n Code-node output contract: an array of { json, binary } objects.
return results;

/**
 * ═══════════════════════════════════════════════════════════
 *  NODE: Attach Image
 *  IN:   Folder Exists? (true)  OR  Create Date Folder
 *  OUT:  All receipt fields + folderId + image binary
 * ═══════════════════════════════════════════════════════════
 *  This is the CONVERGENCE point. Everything the remaining
 *  nodes need is assembled here, in one shape.
 * ═══════════════════════════════════════════════════════════
 */

// The original item: receipt fields in .json, photo in .binary.
// Safe to use .first() because Telegram fires one execution per message.
const src = $('Prepare Data').first();

// Whichever branch delivered the item, it has an .id holding the
// folder ID — Drive's search result and Drive's create response use
// the SAME field name. That's why no branch detection is needed.
const folderId = $input.first().json.id;

return [{
  json: {
    ...src.json,   // loggedAt, fileName, merchant, totalAmount, ...
    folderId,      // ← the one new field: where to upload
  },

  // ⚠️ Re-attach the photo. Neither the Drive search nor the Drive
  // create response carries binary, so the image was dropped two
  // nodes ago. Without this, Upload to Drive fails: "no binary data".
  binary: src.binary,
}];
